58: /// Build the implicit TileView semantics represented by omitted Python syntax.
59: inline TileView GetImplicitTileView(const std::vector<ExprPtr>& shape,
60:                                     const std::optional<MemorySpace>& memory_space = std::nullopt) {
61:   TileView implicit_view;
62:   implicit_view.valid_shape = shape;
63:   implicit_view.blayout = InferImplicitTileLayoutFromShape(shape);
64: 
65:   if (memory_space.has_value()) {
66:     switch (*memory_space) {
67:       case MemorySpace::Mat:
68:       case MemorySpace::Left:
69:         implicit_view.blayout = TileLayout::col_major;
70:         implicit_view.slayout = TileLayout::row_major;
71:         break;
72:       case MemorySpace::Right:
73:         implicit_view.slayout = TileLayout::col_major;
74:         break;
75:       case MemorySpace::Acc:
76:         implicit_view.blayout = TileLayout::col_major;
77:         implicit_view.slayout = TileLayout::row_major;
78:         implicit_view.fractal = 1024;
79:         break;
80:       default:
81:         break;
82:     }
83:   }
84: 
85:   return implicit_view;

345: /// Build the replacement statements for one Mat-resident matmul or matmul_acc.
