347: RewriteResult BuildKLoopRewrite(const KLoopRewrite& r) {
348:   const Span sp = r.original->span_;
349:   const std::string base = r.name_base.empty() ? r.original->var_->name_hint_ : r.name_base;
350:   const bool is_acc = r.acc_init != nullptr;
351:   auto& reg = OpRegistry::GetInstance();
352: 
353:   INTERNAL_CHECK_SPAN(r.k < r.K, sp) << "Internal error: BuildKLoopRewrite expects a tiled K (k < K), got k="
354:                                      << r.k << ", K=" << r.K;
355: 
356:   // K-block decomposition.  With allow_k_boundary the chosen k need not divide
357:   // K: the reduction is `num_full` full blocks of width k plus a final partial
358:   // block of width `k_eff = K - num_full*k` (k_eff == 0 when k divides K — the
359:   // legacy uniform loop).  K and k are 16-aligned, so k_eff is itself 16-aligned —
360:   // an ordinary matmul_acc block (ptoas requires 16-aligned tile cols).
361:   const int64_t num_full = r.K / r.k;
362:   const int64_t k_full = num_full * r.k;
363:   const int64_t k_eff = r.K - k_full;
364:   const bool has_tail = k_eff > 0;
365: 
366:   std::vector<StmtPtr> out;
367: 
368:   // Iter-arg init for the pipelined K-loop (only when there are >= 2 full
369:   // blocks).  Emitted FIRST — before the optional Vec->Mat staging below — so a
370:   // k that divides K yields byte-identical output to the pre-peel emitter.  For
371:   // matmul_acc the caller's accumulator is the init directly; for plain matmul a
372:   // fresh Acc-resident ``tile.create`` placeholder that the first iteration's
373:   // ``tile.matmul`` overwrites (the Nz TileView matches, so iter_arg / yield /
374:   // return_var stay Acc-typed).
375:   ExprPtr loop_init;
376:   TypePtr loop_iter_type;
377:   if (num_full >= 2) {
378:     if (is_acc) {
379:       loop_init = r.acc_init;
380:       loop_iter_type = r.acc_init->GetType();
381:     } else {
382:       auto acc_dtype = As<TileType>(r.original->var_->GetType())->dtype_;
383:       auto c_init = BuildAccInit(r.m, r.n, acc_dtype, base + "_l0_init", sp);
384:       out.push_back(c_init);
385:       loop_init = c_init->var_;
386:       loop_iter_type = c_init->var_->GetType();
387:     }
388:   }
389: 
390:   // A Vec-resident left operand (fused-attention PV / ``score·V``) is staged into
391:   // Mat once, before any K block, so each extract slices from Mat exactly like
392:   // the QK path — and so ``ExpandMixedKernel`` can lower the Vec→Mat crossing via
393:   // its ``tile.move`` handshake (``CollectCVBoundaryMoves`` only matches
394:   // ``tile.move``).  Mat-resident left operands extract directly.
395:   VarPtr lhs_extract_src = r.lhs_src;
396:   if (r.stage_lhs_to_mat) {
397:     auto lhs_mat = BuildMoveToMat(r.lhs_src, base + "_l0_lmat", sp);
398:     out.push_back(lhs_mat);
399:     lhs_extract_src = lhs_mat->var_;
400:   }
401: 
402:   ExprPtr mi_off = r.mi ? r.mi : MakeIndex(0, sp);
403:   ExprPtr ni_off = r.ni ? r.ni : MakeIndex(0, sp);
404: 
405:   // Emit one straight-line K block ``[m, kb] x [kb, n]`` at static K-offset
406:   // ``ko``, accumulating into ``acc_in`` (``tile.matmul_acc``) or starting fresh
407:   // (``tile.matmul`` when ``acc_in`` is null).  Used for the single-full-block
408:   // (num_full == 1) and partial-tail cases; the multi-block case pipelines below.
409:   auto emit_block = [&](int64_t ko, int64_t kb, const ExprPtr& acc_in, const std::string& tag) -> VarPtr {
410:     auto sa = BuildExtract(lhs_extract_src, {r.m, kb}, mi_off, MakeIndex(ko, sp), MemorySpace::Left,
411:                            base + "_l0_a" + tag, sp);
412:     auto sb = BuildExtract(r.rhs_src, {kb, r.n}, MakeIndex(ko, sp), ni_off, MemorySpace::Right,
413:                            base + "_l0_b" + tag, sp);
414:     ExprPtr call = acc_in ? reg.Create("tile.matmul_acc", {acc_in, sa->var_, sb->var_}, sp)
415:                           : reg.Create("tile.matmul", {sa->var_, sb->var_}, sp);
416:     auto cvar = std::make_shared<Var>(base + "_l0_c" + tag, call->GetType(), sp);
417:     out.push_back(sa);
418:     out.push_back(sb);
419:     out.push_back(std::make_shared<AssignStmt>(cvar, call, sp));
420:     return cvar;
421:   };
422: 
423:   // --- Full blocks: a pipelined K-loop when there are >= 2 of them, else a
424:   //     single straight-line block (a 1-trip pipeline loop would be degenerate).
425:   VarPtr main_var;
426:   if (num_full >= 2) {
427:     auto ko_var = std::make_shared<Var>(base + "_l0_ko", std::make_shared<ScalarType>(DataType::INDEX), sp);
428:     auto c_iter = std::make_shared<IterArg>(base + "_l0_c", loop_iter_type, loop_init, sp);
429:     auto sa =
430:         BuildExtract(lhs_extract_src, {r.m, r.k}, mi_off, ko_var, MemorySpace::Left, base + "_l0_a", sp);
431:     auto sb = BuildExtract(r.rhs_src, {r.k, r.n}, ko_var, ni_off, MemorySpace::Right, base + "_l0_b", sp);
432:     StmtPtr body = is_acc ? BuildMatmulAccBody(c_iter, sa, sb, base, sp)
433:                           : BuildMatmulBody(ko_var, c_iter, sa, sb, base, sp);
434:     std::vector<std::pair<std::string, std::any>> attrs = {{kPipelineStagesAttr, /*pipeline_stages=*/2}};
435:     // Loop return var: an intermediate when a partial tail follows (named
436:     // distinctly so round-trip names stay unique), else the final result.
437:     auto rv =
438:         std::make_shared<Var>(has_tail ? base + "_l0_kmain" : base, loop_iter_type, r.original->var_->span_);
439:     auto for_stmt = std::make_shared<ForStmt>(
440:         ko_var, MakeIndex(0, sp), MakeIndex(k_full, sp), MakeIndex(r.k, sp), std::vector<IterArgPtr>{c_iter},
441:         body, std::vector<VarPtr>{rv}, sp, ForKind::Pipeline, std::move(attrs));
442:     out.push_back(for_stmt);
443:     main_var = rv;
444:   } else {
