347:   // In a boxed (NZ/fractal) layout — i.e. an L1/Mat matmul operand — the inner
348:   // box has a fixed granularity, and pto.subview requires the *physical* size to
349:   // be a whole number of boxes per dim (ptoas: "boxed layout subview sizes must
350:   // be multiples of inner shape"). A per-row gather writes a single row, so we
351:   // carve a box-aligned physical sub-region (size = phys_rows x phys_cols) but
352:   // mark only the real extent valid (valid = sv_rows x sv_cols); the tload then
353:   // fills just that row. ND tiles (Vec, slayout=none_box) have no inner box and
354:   // use the exact per-row size.
355:   const bool boxed = view_info.slayout != ir::TileLayout::none_box;
356:   auto round_up = [](int64_t n, int64_t mult) { return ((n + mult - 1) / mult) * mult; };
357:   // NZ fractal granularity: M0 = 16 rows; the C0 lane count along columns is
358:   // fractal_bytes / dtype_bytes / M0 (both collapse to 16 for fp16/bf16).
359:   constexpr int64_t kNZFractalRows = 16;
360:   const int64_t dtype_bytes = std::max<int64_t>(1, static_cast<int64_t>(dst_tile_type->dtype_.GetBit()) / 8);
361:   const int64_t box_cols =
362:       view_info.fractal > 0
363:           ? std::max<int64_t>(1, static_cast<int64_t>(view_info.fractal) / dtype_bytes / kNZFractalRows)
364:           : kNZFractalRows;
365:   const int64_t phys_rows = boxed ? round_up(sv_rows, kNZFractalRows) : sv_rows;

