651:   /// Auto-bridge TensorType args to the memory space required by input_reqs.
652:   /// Returns the (possibly modified) args and any load statements to prepend.
653:   std::pair<std::vector<ExprPtr>, std::vector<StmtPtr>> BridgeInputSpaces(
654:       const CallPtr& call, const std::unordered_map<size_t, InputSpaceReq>& input_reqs) {
655:     if (input_reqs.empty()) return {call->args_, {}};
656: 
657:     auto args = call->args_;
658:     std::vector<StmtPtr> stmts;
659: 
660:     // An operand of rank > 2 means this matmul lowers to tile.batch_matmul, not
661:     // tile.matmul (see the rank dispatch in op_conversion_registry.cpp).
662:     //
663:     // Both 2D tile.matmul AND ND tile.batch_matmul realise a transposed operand
664:     // as a zero-copy tile.transpose_view over ONE natural load/move (issues #1776
665:     // / ND extension). FlattenTileNdTo2D slices the whole transposed view per
666:     // batch; the tile-level (batch_)matmul carries no transpose semantic.
667: 
668:     // Emit a `tile.load` of `arg` (TensorType) into `space`, append its AssignStmt,
669:     // and return the bound load Var. The load is always natural; a transposed
670:     // operand is realised by a zero-copy tile.transpose_view on the result.
671:     auto emit_load = [&](const ExprPtr& arg, const TensorTypePtr& tensor_type, MemorySpace space,
672:                          size_t idx) -> VarPtr {
673:       auto offsets = MakeZeroOffsets(tensor_type->shape_.size(), call->span_);
674:       auto shapes = MakeShapeTuple(tensor_type->shape_, call->span_);
675:       std::vector<std::pair<std::string, std::any>> load_kw = {{"target_memory", space}};
676:       auto load = op_registry_.Create("tile.load", {arg, offsets, shapes, shapes}, load_kw, call->span_);
677:       std::string var_name;
678:       if (auto var = As<Var>(arg)) {
679:         auto space_str = MemorySpaceToString(space);
680:         std::transform(space_str.begin(), space_str.end(), space_str.begin(),
681:                        [](unsigned char c) { return std::tolower(c); });
682:         var_name = var->name_hint_ + "_" + space_str;
683:       } else {
684:         var_name = "bridged_" + std::to_string(idx);
685:       }
686:       auto load_var = std::make_shared<Var>(var_name, load->GetType(), call->span_);
687:       stmts.push_back(std::make_shared<AssignStmt>(load_var, load, call->span_));
688:       return load_var;
689:     };
